parameters.jsCode:
// Voice platforms wrap tool calls differently. VAPI nests them under
// message.toolCalls, Retell sends args at the top level, and a plain test POST
// sends flat JSON. Read all three shapes here so nothing downstream has to.
const body = $json.body || $json || {};

let args = {};
let toolCallId = '';

const vapiCall = body.message && Array.isArray(body.message.toolCalls) ? body.message.toolCalls[0] : null;
if (vapiCall) {
  toolCallId = String(vapiCall.id || '');
  const raw = vapiCall.function ? vapiCall.function.arguments : {};
  args = typeof raw === 'string' ? JSON.parse(raw || '{}') : (raw || {});
} else if (body.args && typeof body.args === 'object') {
  args = body.args;
  toolCallId = String(body.call_id || body.callId || '');
} else {
  args = body;
  toolCallId = String(body.toolCallId || body.callId || '');
}

function pick(keys) {
  for (const k of keys) {
    const v = args[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}

const action = pick(['action', 'intent', 'operation']).toLowerCase() || 'find_slots';

return [{
  json: {
    action: action,
    toolCallId: toolCallId,
    callerName: pick(['name', 'caller_name', 'callerName', 'customer_name']),
    callerPhone: pick(['phone', 'caller_phone', 'callerPhone', 'phone_number']),
    service: pick(['service', 'reason', 'service_type']) || 'Appointment',
    notes: pick(['notes', 'details', 'description']),
    spokenTime: pick(['when', 'requested_time', 'spoken_time', 'preferred_time']),
    slotStart: pick(['slot_start', 'slotStart', 'start', 'start_time']),
    bookingRef: pick(['booking_ref', 'bookingRef', 'reference', 'confirmation_code']),
    receivedAt: new Date().toISOString(),
  },
}];

