parameters.jsCode:
// The slot engine. A voice caller is waiting, so availability is worked out
// here in code rather than by letting a model guess at a calendar. Everything
// is compared in epoch milliseconds, and the business timezone comes from the
// sheet as a fixed UTC offset so the maths stays predictable.
const cfgRows = $('Load Business Hours').all().map(function (i) { return i.json; });
const parsed = $('Understand Requested Time').first().json.output || {};
const request = $('Read Tool Call').first().json;
const busyItems = $input.all().map(function (i) { return i.json; });

if (!cfgRows.length) {
  throw new Error('The Business Hours tab is empty. Add one row per weekday before using this workflow.');
}

const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const offset = String(cfgRows[0]['UTC Offset'] || '+00:00').trim();
const minNotice = Number(cfgRows[0]['Min Notice Hours'] || 2) || 2;

const byDay = {};
cfgRows.forEach(function (r) {
  const name = String(r['Weekday'] || '').trim();
  if (name) byDay[name.toLowerCase()] = r;
});

function minutesOf(hhmm) {
  const m = String(hhmm || '').match(/^(\d{1,2}):(\d{2})$/);
  return m ? (+m[1]) * 60 + (+m[2]) : null;
}

function pad(n) { return (n < 10 ? '0' : '') + n; }

function isoAt(dateStr, totalMinutes) {
  return dateStr + 'T' + pad(Math.floor(totalMinutes / 60)) + ':' + pad(totalMinutes % 60) + ':00' + offset;
}

// Busy windows, each widened by the buffer so appointments do not touch.
const busy = [];
busyItems.forEach(function (e) {
  const s = e.start && (e.start.dateTime || e.start.date);
  const t = e.end && (e.end.dateTime || e.end.date);
  if (!s || !t) return;
  busy.push({ start: Date.parse(s), end: Date.parse(t), day: String(s).slice(0, 10) });
});

// How many appointments each day already holds, for the daily cap.
const perDay = {};
busy.forEach(function (b) { perDay[b.day] = (perDay[b.day] || 0) + 1; });

const windowStart = String(parsed.startDate || new Date().toISOString().slice(0, 10));
const windowEnd = String(parsed.endDate || windowStart);
const preference = String(parsed.partOfDay || 'any').toLowerCase();
const blackout = String(cfgRows[0]['Blackout Dates'] || '')
  .split(',').map(function (s) { return s.trim(); }).filter(Boolean);

const earliest = Date.now() + minNotice * 60 * 60 * 1000;
const found = [];
const cursor = new Date(windowStart + 'T00:00:00Z');
const limit = new Date(windowEnd + 'T00:00:00Z');
let dayCount = 0;

while (cursor.getTime() <= limit.getTime() && dayCount < 14 && found.length < 3) {
  dayCount += 1;
  const dateStr = cursor.toISOString().slice(0, 10);
  const cfg = byDay[DAYS[cursor.getUTCDay()].toLowerCase()];
  cursor.setUTCDate(cursor.getUTCDate() + 1);

  if (!cfg) continue;
  if (blackout.indexOf(dateStr) !== -1) continue;
  if (String(cfg['Closed'] || '').toLowerCase() === 'yes') continue;

  const open = minutesOf(cfg['Open']);
  const close = minutesOf(cfg['Close']);
  if (open === null || close === null || close <= open) continue;

  const slotLen = Number(cfg['Slot Minutes'] || 60) || 60;
  const buffer = Number(cfg['Buffer Minutes'] || 0) || 0;
  const maxPerDay = Number(cfg['Max Per Day'] || 99) || 99;
  if ((perDay[dateStr] || 0) >= maxPerDay) continue;

  for (let start = open; start + slotLen <= close; start += slotLen) {
    if (found.length >= 3) break;

    const hour = Math.floor(start / 60);
    if (preference === 'morning' && hour >= 12) continue;
    if (preference === 'afternoon' && (hour < 12 || hour >= 17)) continue;
    if (preference === 'evening' && hour < 17) continue;

    const startMs = Date.parse(isoAt(dateStr, start));
    const endMs = Date.parse(isoAt(dateStr, start + slotLen));
    if (startMs < earliest) continue;

    const clash = busy.some(function (b) {
      return startMs < (b.end + buffer * 60000) && (b.start - buffer * 60000) < endMs;
    });
    if (clash) continue;

    found.push({
      startIso: isoAt(dateStr, start),
      endIso: isoAt(dateStr, start + slotLen),
      date: dateStr,
      weekday: DAYS[new Date(dateStr + 'T00:00:00Z').getUTCDay()],
      spoken: DAYS[new Date(dateStr + 'T00:00:00Z').getUTCDay()] + ' at ' +
        ((hour % 12) || 12) + (start % 60 ? ':' + pad(start % 60) : '') + (hour < 12 ? ' in the morning' : (hour < 17 ? ' in the afternoon' : ' in the evening')),
      durationMinutes: slotLen,
    });
  }
}

return [{
  json: {
    slots: found,
    slotCount: found.length,
    spokenOffer: found.length
      ? 'I can offer ' + found.map(function (s) { return s.spoken; }).join(', or ') + '. Which suits you?'
      : 'I could not find an open slot in that window.',
    searchedFrom: windowStart,
    searchedTo: windowEnd,
    preference: preference,
    toolCallId: request.toolCallId,
    callerName: request.callerName,
    callerPhone: request.callerPhone,
    service: request.service,
  },
}];

// A short reference the caller can repeat back on the phone, derived from the
// slot and the phone number so the same booking never gets two references.
const r = $('Read Tool Call').first().json;
const seed = (r.slotStart + '|' + r.callerPhone);

let hash = 0;
for (let i = 0; i < seed.length; i += 1) {
  hash = ((hash << 5) - hash + seed.charCodeAt(i)) | 0;
}

const letters = 'ACDEFGHJKLMNPQRTUVWXY';
let code = '';
let n = Math.abs(hash);
for (let i = 0; i < 2; i += 1) { code += letters[n % letters.length]; n = Math.floor(n / letters.length); }
code += '-' + String(Math.abs(hash) % 10000).padStart(4, '0');

const start = new Date(r.slotStart);
const durationMinutes = 60;
const end = new Date(start.getTime() + durationMinutes * 60000);

if (isNaN(start.getTime())) {
  throw new Error('The voice agent sent an unreadable slot_start value: ' + r.slotStart);
}

return [{
  json: Object.assign({}, r, {
    bookingRef: code,
    slotStartIso: start.toISOString(),
    slotEndIso: end.toISOString(),
    durationMinutes: durationMinutes,
    bookedOn: new Date().toISOString().slice(0, 10),
  }),
}];

